{"file_path": "src/lib/mock/mock-db.ts", "initial_content": "/**
 * Mock Database
 * In-memory data store with JSON file persistence for development mode
 */

import { Project, User, Section, Template } from '@/lib/models';

interface MockDBStore {
  users: User[];
  projects: Project[];
  sections: Section[];
  templates: Template[];
  agents: Record<string, any>;
  transactions: Record<string, any>;
}

class MockDB {
  private data: MockDBStore = {
    users: [],
    projects: [],
    sections: [],
    templates: [],
    agents: {},
    transactions: {},
  };

  private initialized = false;

  async initialize() {
    if (this.initialized) return;

    try {
      // Load seed data
      const usersData = await import('./data/users.json');
      const projectsData = await import('./data/projects.json');
      const sectionsData = await import('./data/sections.json');
      const templatesData = await import('./data/templates.json');
      const agentsData = await import('./data/agents.json');

      this.data = {
        users: usersData.default || usersData,
        projects: projectsData.default || projectsData,
        sections: sectionsData.default || sectionsData,
        templates: templatesData.default || templatesData,
        agents: agentsData.default || agentsData,
        transactions: {},
      };

      this.initialized = true;
    } catch (error) {
      console.warn('Failed to load mock data seed files', error);
      this.initialized = true;
    }
  }

  // User operations
  async getUser(userId: string): Promise<User | null> {
    await this.initialize();
    return this.data.users.find(u => u.id === userId) || null;
  }

  async getUserByEmail(email: string): Promise<User | null> {
    await this.initialize();
    return this.data.users.find(u => u.email === email) || null;
  }

  async createUser(user: User): Promise<User> {
    await this.initialize();
    this.data.users.push(user);
    return user;
  }

  async updateUser(userId: string, updates: Partial<User>): Promise<User | null> {
    await this.initialize();
    const idx = this.data.users.findIndex(u => u.id === userId);
    if (idx === -1) return null;
    this.data.users[idx] = { ...this.data.users[idx], ...updates };
    return this.data.users[idx];
  }

  async getAllUsers(): Promise<User[]> {
    await this.initialize();
    return this.data.users;
  }

  // Project operations
  async getProject(projectId: string): Promise<Project | null> {
    await this.initialize();
    return this.data.projects.find(p => p.id === projectId) || null;
  }

  async getUserProjects(userId: string): Promise<Project[]> {
    await this.initialize();
    return this.data.projects.filter(p => p.userId === userId);
  }

  async createProject(project: Project): Promise<Project> {
    await this.initialize();
    this.data.projects.push(project);
    return project;
  }

  async updateProject(projectId: string, updates: Partial<Project>): Promise<Project | null> {
    await this.initialize();
    const idx = this.data.projects.findIndex(p => p.id === projectId);
    if (idx === -1) return null;
    this.data.projects[idx] = { ...this.data.projects[idx], ...updates };
    return this.data.projects[idx];
  }

  async deleteProject(projectId: string): Promise<boolean> {
    await this.initialize();
    const idx = this.data.projects.findIndex(p => p.id === projectId);
    if (idx === -1) return false;
    this.data.projects.splice(idx, 1);
    return true;
  }

  // Section operations
  async getSection(sectionId: string): Promise<Section | null> {
    await this.initialize();
    return this.data.sections.find(s => s.id === sectionId) || null;
  }

  async getProjectSections(projectId: string): Promise<Section[]> {
    await this.initialize();
    return this.data.sections.filter(s => s.projectId === projectId);
  }

  async createSection(section: Section): Promise<Section> {
    await this.initialize();
    this.data.sections.push(section);
    return section;
  }

  async updateSection(sectionId: string, updates: Partial<Section>): Promise<Section | null> {
    await this.initialize();
    const idx = this.data.sections.findIndex(s => s.id === sectionId);
    if (idx === -1) return null;
    this.data.sections[idx] = { ...this.data.sections[idx], ...updates };
    return this.data.sections[idx];
  }

  async deleteSection(sectionId: string): Promise<boolean> {
    await this.initialize();
    const idx = this.data.sections.findIndex(s => s.id === sectionId);
    if (idx === -1) return false;
    this.data.sections.splice(idx, 1);
    return true;
  }

  // Template operations
  async getTemplate(templateId: string): Promise<Template | null> {
    await this.initialize();
    return this.data.templates.find(t => t.id === templateId) || null;
  }

  async getAllTemplates(): Promise<Template[]> {
    await this.initialize();
    return this.data.templates;
  }

  async createTemplate(template: Template): Promise<Template> {
    await this.initialize();
    this.data.templates.push(template);
    return template;
  }

  // Query helpers
  async query<T>(collection: keyof MockDBStore, where?: Record<string, any>): Promise<T[]> {
    await this.initialize();
    let results = this.data[collection] as T[];

    if (where) {
      results = results.filter(item => {
        return Object.entries(where).every(([key, value]) => (item as any)[key] === value);
      });
    }

    return results;
  }

  // Clear all data
  async clear() {
    this.data = {
      users: [],
      projects: [],
      sections: [],
      templates: [],
      agents: {},
      transactions: {},
    };
  }
}

export const mockDB = new MockDB();
"}

{"file_path": "src/lib/mock/mock-storage.ts", "initial_content": "/**
 * Mock Storage
 * Simulates Firebase Storage with in-memory file handling
 */

interface MockFile {
  name: string;
  data: string; // base64 encoded
  mimeType: string;
  uploadedAt: Date;
}

class MockStorage {
  private files: Map<string, MockFile> = new Map();

  async uploadFile(path: string, file: File): Promise<string> {
    const reader = new FileReader();
    return new Promise((resolve, reject) => {
      reader.onload = () => {
        const base64 = reader.result as string;
        this.files.set(path, {
          name: file.name,
          data: base64,
          mimeType: file.type,
          uploadedAt: new Date(),
        });
        resolve(path);
      };
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  }

  async getFileUrl(path: string): Promise<string> {
    const file = this.files.get(path);
    if (!file) {
      throw new Error(`File not found: ${path}`);
    }
    return file.data; // Return base64 as data URL
  }

  async deleteFile(path: string): Promise<void> {
    this.files.delete(path);
  }

  async listFiles(folderPath: string): Promise<string[]> {
    return Array.from(this.files.keys()).filter(path => path.startsWith(folderPath));
  }

  async clear(): Promise<void> {
    this.files.clear();
  }
}

export const mockStorage = new MockStorage();
"}

{"file_path": "src/lib/mock/mock-auth.ts", "initial_content": "/**
 * Mock Authentication
 * Simple email/password mock that accepts any credentials
 */

import { User as FirebaseUser } from 'firebase/auth';
import { v4 as uuidv4 } from 'uuid';

export interface MockAuthUser extends Omit<FirebaseUser, 'getIdToken' | 'getIdTokenResult' | 'reload'> {
  uid: string;
  email: string;
  emailVerified: boolean;
  displayName: string | null;
  isAnonymous: boolean;
}

class MockAuth {
  private currentUser: MockAuthUser | null = null;
  private listeners: ((user: MockAuthUser | null) => void)[] = [];

  constructor() {
    // Try to restore session from localStorage
    if (typeof window !== 'undefined') {
      const saved = localStorage.getItem('mock-auth-user');
      if (saved) {
        this.currentUser = JSON.parse(saved);
      }
    }
  }

  async signUp(email: string, password: string): Promise<MockAuthUser> {
    // Simple validation
    if (!email || !password) {
      throw new Error('Email and password are required');
    }

    const user: MockAuthUser = {
      uid: uuidv4(),
      email,
      emailVerified: false,
      displayName: null,
      isAnonymous: false,
      metadata: {
        creationTime: new Date().toISOString(),
        lastSignInTime: new Date().toISOString(),
      },
      providerData: [],
      phoneNumber: null,
      photoURL: null,
      providerId: 'mock',
    } as any;

    this.setCurrentUser(user);
    return user;
  }

  async signIn(email: string, password: string): Promise<MockAuthUser> {
    if (!email || !password) {
      throw new Error('Email and password are required');
    }

    // Mock accepts any email/password combination
    const user: MockAuthUser = {
      uid: uuidv4(),
      email,
      emailVerified: false,
      displayName: null,
      isAnonymous: false,
      metadata: {
        creationTime: new Date().toISOString(),
        lastSignInTime: new Date().toISOString(),
      },
      providerData: [],
      phoneNumber: null,
      photoURL: null,
      providerId: 'mock',
    } as any;

    this.setCurrentUser(user);
    return user;
  }

  async signOut(): Promise<void> {
    this.setCurrentUser(null);
  }

  async updateProfile(updates: { displayName?: string; photoURL?: string }): Promise<void> {
    if (this.currentUser) {
      this.currentUser = {
        ...this.currentUser,
        displayName: updates.displayName ?? this.currentUser.displayName,
        photoURL: updates.photoURL ?? this.currentUser.photoURL,
      };
      this.saveSession();
      this.notifyListeners();
    }
  }

  getCurrentUser(): MockAuthUser | null {
    return this.currentUser;
  }

  onAuthStateChanged(callback: (user: MockAuthUser | null) => void): () => void {
    this.listeners.push(callback);
    // Call immediately with current state
    callback(this.currentUser);

    // Return unsubscribe function
    return () => {
      const idx = this.listeners.indexOf(callback);
      if (idx > -1) this.listeners.splice(idx, 1);
    };
  }

  private setCurrentUser(user: MockAuthUser | null) {
    this.currentUser = user;
    this.saveSession();
    this.notifyListeners();
  }

  private notifyListeners() {
    this.listeners.forEach(listener => listener(this.currentUser));
  }

  private saveSession() {
    if (typeof window !== 'undefined') {
      if (this.currentUser) {
        localStorage.setItem('mock-auth-user', JSON.stringify(this.currentUser));
      } else {
        localStorage.removeItem('mock-auth-user');
      }
    }
  }
}

export const mockAuth = new MockAuth();
"}

