{"file_path": "src/lib/mock/mock-api-adapter.ts", "initial_content": "/**
 * Mock API Adapter
 * Provides centralized access to mock DB for API routes
 */

import { mockConfig } from '@/lib/config';
import { mockDB } from './mock-db';
import { mockAuth } from './mock-auth';
import { mockStorage } from './mock-storage';

/**
 * Get the appropriate data source based on mock mode
 */
export const getDataAdapter = () => {
  if (!mockConfig.enabled) {
    throw new Error('Mock adapter should only be used when NEXT_PUBLIC_USE_MOCK_DATA is enabled');
  }
  return mockDB;
};

/**
 * Get the appropriate auth provider based on mock mode
 */
export const getAuthAdapter = () => {
  if (!mockConfig.enabled) {
    throw new Error('Mock adapter should only be used when NEXT_PUBLIC_USE_MOCK_DATA is enabled');
  }
  return mockAuth;
};

/**
 * Get the appropriate storage provider based on mock mode
 */
export const getStorageAdapter = () => {
  if (!mockConfig.enabled) {
    throw new Error('Mock adapter should only be used when NEXT_PUBLIC_USE_MOCK_DATA is enabled');
  }
  return mockStorage;
};

/**
 * Utility to check if mock mode is active
 */
export const isMockModeActive = (): boolean => {
  return mockConfig.enabled;
};

/**
 * Mock Firebase User object for API responses
 */
export interface MockFirebaseUser {
  uid: string;
  email: string;
  emailVerified: boolean;
  displayName: string | null;
  photoURL: string | null;
  isAnonymous: boolean;
}

/**
 * Get current user from mock auth (server-side safe)
 */
export const getCurrentMockUser = (): MockFirebaseUser | null => {
  const user = mockAuth.getCurrentUser();
  if (!user) return null;

  return {
    uid: user.uid,
    email: user.email,
    emailVerified: user.emailVerified,
    displayName: user.displayName,
    photoURL: user.photoURL,
    isAnonymous: user.isAnonymous,
  };
};

/**
 * Verify mock user exists
 */
export const verifyMockUser = async (uid: string): Promise<boolean> => {
  const db = getDataAdapter();
  const user = await db.getUser(uid);
  return !!user;
};
"}

