{"file_path": "src/lib/mock/api-route-helper.ts", "initial_content": "/**
 * API Route Helper for Mock Mode
 * Provides utilities for API routes to work with both Firebase and mock data
 */

import { mockConfig } from '@/lib/config';
import { getDataAdapter, getCurrentMockUser, isMockModeActive } from './mock-api-adapter';

export interface ApiRouteContext {
  userId?: string;
  isMockMode: boolean;
}

/**
 * Extract user context from request
 * In mock mode, returns the current mock user
 * In Firebase mode, would need to verify the token
 */
export async function getApiRouteContext(request?: Request): Promise<ApiRouteContext> {
  const isMock = isMockModeActive();

  if (isMock) {
    const mockUser = getCurrentMockUser();
    return {
      userId: mockUser?.uid,
      isMockMode: true,
    };
  }

  return {
    isMockMode: false,
  };
}

/**
 * Wrapper for API routes that need database access
 * Automatically uses mock DB when in mock mode
 */
export async function withMockSupport<T>(
  handler: (context: ApiRouteContext, db: typeof import('./mock-db').mockDB) => Promise<T>
): Promise<T> {
  const context = await getApiRouteContext();

  if (context.isMockMode) {
    const db = getDataAdapter();
    return handler(context, db);
  }

  throw new Error('Non-mock mode requires Firebase setup');
}

/**
 * Response wrapper for consistent API responses
 */
export function successResponse<T>(data: T, status = 200) {
  return new Response(JSON.stringify({ success: true, data }), {
    status,
    headers: { 'Content-Type': 'application/json' },
  });
}

export function errorResponse(message: string, status = 400) {
  return new Response(JSON.stringify({ success: false, error: message }), {
    status,
    headers: { 'Content-Type': 'application/json' },
  });
}
"}

{"file_path": "src/lib/mock/examples/signup-route-example.ts", "initial_content": "/**
 * Example: Mock-Compatible API Route
 * This shows how to update an API route to work with mock mode
 * 
 * Usage in src/app/api/auth/signup/route.ts:
 * 1. Import mock utilities
 * 2. Check if mock mode is active
 * 3. Use mock DB/auth adapters when in mock mode
 */

import { mockConfig } from '@/lib/config';
import { getDataAdapter, getAuthAdapter } from '../mock-api-adapter';
import { v4 as uuidv4 } from 'uuid';
import { z } from 'zod';

const signupSchema = z.object({
  email: z.string().email('Invalid email address'),
  password: z.string().min(6, 'Password must be at least 6 characters long'),
  name: z.string().min(1, 'Name is required'),
});

export async function POST(req: Request) {
  try {
    const body = await req.json();
    const validation = signupSchema.safeParse(body);
    if (!validation.success) {
      return new Response(JSON.stringify({ error: 'Validation failed' }), { status: 400 });
    }

    const { email, password, name } = validation.data;

    if (mockConfig.enabled) {
      // Mock Mode Implementation
      const db = getDataAdapter();
      const auth = getAuthAdapter();

      // Check if user already exists
      const existingUser = await db.getUserByEmail(email);
      if (existingUser) {
        return new Response(
          JSON.stringify({ error: 'Email address is already in use by another account.' }),
          { status: 409 }
        );
      }

      // Create mock user
      const userId = uuidv4();
      const newUser = {
        id: userId,
        email,
        displayName: name,
        photoURL: null,
        credits: 10, // Default credits for new users
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
        role: 'user',
        language: 'en',
        stripeCustomerId: null,
      };

      await db.createUser(newUser);

      // Also sign in the user
      await auth.signUp(email, password);

      return new Response(
        JSON.stringify({
          success: true,
          data: {
            user: {
              uid: userId,
              email: email,
            },
          },
        }),
