{"file_path": "src/hooks/use-mock-mode.ts", "initial_content": "'use client';

import { mockConfig } from '@/lib/config';
import { useEffect, useState } from 'react';

/**
 * Hook to check if mock mode is enabled
 * Useful for conditional rendering or logging in development
 */
export function useMockMode() {
  const [isMockMode] = useState(() => mockConfig.enabled);

  return {
    isMockMode,
    isDev: process.env.NODE_ENV === 'development',
    isProduction: process.env.NODE_ENV === 'production',
  };
}

/**
 * Hook to log mock mode status on mount
 * Useful for debugging in development
 */
export function useLogMockModeStatus() {
  useEffect(() => {
    if (mockConfig.enabled) {
      console.log('🔷 Running in MOCK MODE - using in-memory data');
      console.log('Test users:');
      console.log('  - demo@example.com (100 credits)');
      console.log('  - admin@example.com (1000 credits, admin)');
      console.log('Password: any (mock auth accepts all)');
    } else {
      console.log('🔶 Running in FIREBASE MODE');
    }
  }, []);
}

/**
 * Hook to get mock auth state
 * Returns mock user data when in mock mode
 */
export function useMockAuthState() {
  const [mockUser, setMockUser] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    if (!mockConfig.enabled) {
      setIsLoading(false);
      return;
    }

    try {
      const { mockAuth } = require('@/lib/mock/mock-auth');

      setIsLoading(true);
      const unsubscribe = mockAuth.onAuthStateChanged((user: any) => {
        setMockUser(user);
        setIsLoading(false);
        setError(null);
      });

      return () => unsubscribe();
    } catch (err) {
      setError(err instanceof Error ? err : new Error('Failed to load mock auth'));
      setIsLoading(false);
    }
  }, []);

  return { mockUser, isLoading, error };
}

/**
 * Hook to interact with mock auth
 * Provides sign up, sign in, sign out methods
 */
export function useMockAuthMethods() {
  const handleSignUp = async (email: string, password: string) => {
    if (!mockConfig.enabled) {
      throw new Error('Mock mode not enabled');
    }

    try {
      const { mockAuth } = require('@/lib/mock/mock-auth');
      const user = await mockAuth.signUp(email, password);
      return user;
    } catch (error) {
      throw error;
    }
  };

  const handleSignIn = async (email: string, password: string) => {
    if (!mockConfig.enabled) {
      throw new Error('Mock mode not enabled');
    }

    try {
      const { mockAuth } = require('@/lib/mock/mock-auth');
      const user = await mockAuth.signIn(email, password);
      return user;
    } catch (error) {
      throw error;
    }
  };

  const handleSignOut = async () => {
    if (!mockConfig.enabled) {
      throw new Error('Mock mode not enabled');
    }

    try {
      const { mockAuth } = require('@/lib/mock/mock-auth');
      await mockAuth.signOut();
    } catch (error) {
      throw error;
    }
  };

  return {
    signUp: handleSignUp,
    signIn: handleSignIn,
    signOut: handleSignOut,
  };
}

/**
 * Hook to access mock data directly in components
 * Useful for debugging or listing available data
 */
export function useMockData() {
  const [data, setData] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  const loadData = async (collection: string) => {
    if (!mockConfig.enabled) {
      setError(new Error('Mock mode not enabled'));
      return;
    }

    try {
      setIsLoading(true);
      const { mockDB } = require('@/lib/mock/mock-db');
      const results = await mockDB.query(collection);
      setData(results);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err : new Error('Failed to load mock data'));
    } finally {
      setIsLoading(false);
    }
  };

  return { data, isLoading, error, loadData };
}
"}

{"file_path": "src/db/schema.ts", "initial_content": "import { pgTable, text, integer, timestamp, boolean, serial, varchar, bytea, jsonb, numeric, index, foreignKey } from 'drizzle-orm/pg-core';
import { relations } from 'drizzle-orm';

// Users table
export const users = pgTable(
  'users',
  {
    id: serial('id').primaryKey(),
    email: varchar('email', { length: 255 }).notNull().unique(),
    name: varchar('name', { length: 255 }),
    password: varchar('password', { length: 255 }).notNull(),
    credits: integer('credits').default(10),
    role: varchar('role', { length: 50 }).default('user'), // user, admin
    language: varchar('language', { length: 10 }).default('en'),
    stripeCustomerId: varchar('stripe_customer_id', { length: 255 }),
    photoURL: text('photo_url'),
    createdAt: timestamp('created_at').defaultNow(),
    updatedAt: timestamp('updated_at').defaultNow(),
  },
  (table) => ({
    emailIdx: index('users_email_idx').on(table.email),
  })
);

// Projects table
export const projects = pgTable(
  'projects',
  {
    id: serial('id').primaryKey(),
    userId: integer('user_id').notNull(),
    title: varchar('title', { length: 255 }).notNull(),
    description: text('description'),
    content: text('content'),
    status: varchar('status', { length: 50 }).default('draft'), // draft, completed, archived
    language: varchar('language', { length: 10 }).default('en'),
    templateId: integer('template_id'),
    lastModifiedBy: integer('last_modified_by'),
    metadata: jsonb('metadata'), // wordCount, pageCount, etc
    createdAt: timestamp('created_at').defaultNow(),
    updatedAt: timestamp('updated_at').defaultNow(),
  },
  (table) => ({
    userIdIdx: index('projects_user_id_idx').on(table.userId),
    userFk: foreignKey({ columns: [table.userId], foreignColumns: [users.id] }).onDelete('cascade'),
  })
);

// Sections table
export const sections = pgTable(
  'sections',
  {
    id: serial('id').primaryKey(),
    projectId: integer('project_id').notNull(),
    title: varchar('title', { length: 255 }).notNull(),
    content: text('content'),
    order: integer('order').default(0),
    status: varchar('status', { length: 50 }).default('draft'),
    metadata: jsonb('metadata'),
    createdAt: timestamp('created_at').defaultNow(),
    updatedAt: timestamp('updated_at').defaultNow(),
  },
  (table) => ({
    projectIdIdx: index('sections_project_id_idx').on(table.projectId),
    projectFk: foreignKey({ columns: [table.projectId], foreignColumns: [projects.id] }).onDelete('cascade'),
  })
);

// Templates table
export const templates = pgTable(
  'templates',
  {
    id: serial('id').primaryKey(),
    name: varchar('name', { length: 255 }).notNull(),
    description: text('description'),
    category: varchar('category', { length: 100 }),
    type: varchar('type', { length: 50 }), // report, presentation, document
    sections: jsonb('sections'), // Array of section definitions
    createdAt: timestamp('created_at').defaultNow(),
    updatedAt: timestamp('updated_at').defaultNow(),
  }
);

// Agents table
export const agents = pgTable(
  'agents',
  {
    id: serial('id').primaryKey(),
    name: varchar('name', { length: 255 }).notNull(),
    description: text('description'),
    category: varchar('category', { length: 100 }),
    capabilities: jsonb('capabilities'), // Array of capabilities
    model: varchar('model', { length: 100 }),
    createdAt: timestamp('created_at').defaultNow(),
  }
);

// Agent Categories table
export const agentCategories = pgTable(
  'agent_categories',
  {
    id: serial('id').primaryKey(),
    name: varchar('name', { length: 255 }).notNull(),
    description: text('description'),
    createdAt: timestamp('created_at').defaultNow(),
  }
);

// File Storage table (for hybrid approach: small files < 1MB)
export const fileStorage = pgTable(
  'file_storage',
  {
    id: serial('id').primaryKey(),
    userId: integer('user_id').notNull(),
    filename: varchar('filename', { length: 255 }).notNull(),
    mimeType: varchar('mime_type', { length: 100 }),
    size: integer('size').notNull(), // in bytes
    data: bytea('data'), // For files < 1MB
    storagePath: varchar('storage_path', { length: 255 }), // For files > 1MB (path on disk)
    createdAt: timestamp('created_at').defaultNow(),
  },
  (table) => ({
    userIdIdx: index('file_storage_user_id_idx').on(table.userId),
    userFk: foreignKey({ columns: [table.userId], foreignColumns: [users.id] }).onDelete('cascade'),
  })
);

// Transactions table (for credits/payments)
export const transactions = pgTable(
  'transactions',
  {
    id: serial('id').primaryKey(),
    userId: integer('user_id').notNull(),
    type: varchar('type', { length: 50 }), // purchase, usage, refund
    amount: numeric('amount', { precision: 10, scale: 2 }),
    credits: integer('credits'),
    description: text('description'),
    status: varchar('status', { length: 50 }).default('completed'),
    createdAt: timestamp('created_at').defaultNow(),
  },
  (table) => ({
    userIdIdx: index('transactions_user_id_idx').on(table.userId),
    userFk: foreignKey({ columns: [table.userId], foreignColumns: [users.id] }).onDelete('cascade'),
  })
);

// Notifications table
export const notifications = pgTable(
  'notifications',
  {
    id: serial('id').primaryKey(),
    userId: integer('user_id').notNull(),
    type: varchar('type', { length: 100 }),
    title: varchar('title', { length: 255 }),
    message: text('message'),
    read: boolean('read').default(false),
    data: jsonb('data'),
    createdAt: timestamp('created_at').defaultNow(),
  },
  (table) => ({
    userIdIdx: index('notifications_user_id_idx').on(table.userId),
    userFk: foreignKey({ columns: [table.userId], foreignColumns: [users.id] }).onDelete('cascade'),
  })
);

// Relations
export const usersRelations = relations(users, ({ many }) => ({
  projects: many(projects),
  files: many(fileStorage),
  transactions: many(transactions),
  notifications: many(notifications),
}));

export const projectsRelations = relations(projects, ({ one, many }) => ({
  user: one(users, {
    fields: [projects.userId],
    references: [users.id],
  }),
  sections: many(sections),
}));

export const sectionsRelations = relations(sections, ({ one }) => ({
  project: one(projects, {
    fields: [sections.projectId],
    references: [projects.id],
  }),
}));

export const fileStorageRelations = relations(fileStorage, ({ one }) => ({
  user: one(users, {
    fields: [fileStorage.userId],
    references: [users.id],
  }),
}));

export const transactionsRelations = relations(transactions, ({ one }) => ({
  user: one(users, {
    fields: [transactions.userId],
    references: [users.id],
  }),
}));

export const notificationsRelations = relations(notifications, ({ one }) => ({
  user: one(users, {
    fields: [notifications.userId],
    references: [users.id],
  }),
}));
"}

