{"file_path": "src/lib/uploads/storage.ts", "initial_content": "import { db } from '@/db';
import { fileStorage } from '@/db/schema';
import { eq } from 'drizzle-orm';
import fs from 'fs/promises';
import path from 'path';
import { v4 as uuidv4 } from 'uuid';

const FILE_SIZE_LIMIT = 1024 * 1024; // 1MB
const UPLOAD_DIR = path.join(process.cwd(), 'public', 'uploads');

// Ensure upload directory exists
async function ensureUploadDir() {
  try {
    await fs.mkdir(UPLOAD_DIR, { recursive: true });
  } catch (error) {
    console.error('Failed to create upload directory:', error);
  }
}

/**
 * Upload file with hybrid storage (DB for small files, disk for large files)
 */
export async function uploadFile(userId: number, file: File): Promise<number> {
  const buffer = Buffer.from(await file.arrayBuffer());
  const filename = `${uuidv4()}_${file.name}`;
  const mimeType = file.type;
  const size = buffer.length;

  try {
    let storagePath: string | null = null;

    // Large file: store on disk
    if (size > FILE_SIZE_LIMIT) {
      await ensureUploadDir();
      storagePath = path.join(UPLOAD_DIR, filename);
      await fs.writeFile(storagePath, buffer);
    }

    // Insert into database
    const result = await db.insert(fileStorage).values({
      userId,
      filename,
      mimeType,
      size,
      data: size <= FILE_SIZE_LIMIT ? buffer : null, // Store small files in DB
      storagePath: size > FILE_SIZE_LIMIT ? `/uploads/${filename}` : null,
    }).returning({ id: fileStorage.id });

    return result[0].id;
  } catch (error) {
    console.error('File upload error:', error);
    throw error;
  }
}

/**
 * Download file - serves from DB or disk
 */
export async function downloadFile(fileId: number): Promise<Buffer> {
  try {
    const file = await db.query.fileStorage.findFirst({
      where: eq(fileStorage.id, fileId),
    });

    if (!file) {
      throw new Error('File not found');
    }

    // File is in database
    if (file.data) {
      return file.data;
    }

    // File is on disk
    if (file.storagePath) {
      const diskPath = path.join(process.cwd(), 'public', file.storagePath);
      return await fs.readFile(diskPath);
    }

    throw new Error('File data not found');
  } catch (error) {
    console.error('File download error:', error);
    throw error;
  }
}

/**
 * Get file metadata
 */
export async function getFileMetadata(fileId: number) {
  try {
    const file = await db.query.fileStorage.findFirst({
      where: eq(fileStorage.id, fileId),
    });

    if (!file) {
      throw new Error('File not found');
    }

    return {
      id: file.id,
      filename: file.filename,
      mimeType: file.mimeType,
      size: file.size,
      createdAt: file.createdAt,
      url: file.storagePath ? file.storagePath : `/api/files/download/${file.id}`,
    };
  } catch (error) {
    console.error('File metadata error:', error);
    throw error;
  }
}

/**
 * Delete file - from DB and disk
 */
export async function deleteFile(fileId: number): Promise<void> {
  try {
    const file = await db.query.fileStorage.findFirst({
      where: eq(fileStorage.id, fileId),
    });

    if (!file) {
      throw new Error('File not found');
    }

    // Delete from disk if applicable
    if (file.storagePath) {
      const diskPath = path.join(process.cwd(), 'public', file.storagePath);
      try {
        await fs.unlink(diskPath);
      } catch (error) {
        console.warn('Failed to delete disk file:', error);
      }
    }

    // Delete from database
    await db.delete(fileStorage).where(eq(fileStorage.id, fileId));
  } catch (error) {
    console.error('File deletion error:', error);
    throw error;
  }
}

/**
 * List user's files
 */
export async function listUserFiles(userId: number) {
  try {
    const files = await db.query.fileStorage.findMany({
      where: eq(fileStorage.userId, userId),
    });

    return files.map(file => ({
      id: file.id,
      filename: file.filename,
      mimeType: file.mimeType,
      size: file.size,
      createdAt: file.createdAt,
    }));
  } catch (error) {
    console.error('List files error:', error);
    throw error;
  }
}

/**
 * Get total storage usage for user
 */
export async function getUserStorageUsage(userId: number): Promise<number> {
  try {
    const files = await db.query.fileStorage.findMany({
      where: eq(fileStorage.userId, userId),
    });

    return files.reduce((total, file) => total + (file.size || 0), 0);
  } catch (error) {
    console.error('Storage usage error:', error);
    return 0;
  }
}
"}

{"file_path": "src/app/api/files/upload/route.ts", "initial_content": "import { auth } from '@/auth';
import { uploadFile, getUserStorageUsage } from '@/lib/uploads/storage';

const MAX_STORAGE_GB = 5; // 5GB per user

export async function POST(request: Request) {
  try {
    const session = await auth();

    if (!session?.user) {
      return new Response(JSON.stringify({ error: 'Unauthorized' }), {
        status: 401,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    const formData = await request.formData();
    const file = formData.get('file') as File;

    if (!file) {
      return new Response(JSON.stringify({ error: 'No file provided' }), {
        status: 400,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    // Check storage quota
    const currentUsage = await getUserStorageUsage(parseInt((session.user as any).id));
    const maxBytes = MAX_STORAGE_GB * 1024 * 1024 * 1024;

    if (currentUsage + file.size > maxBytes) {
      return new Response(
        JSON.stringify({ error: 'Storage quota exceeded' }),
        {
          status: 413,
          headers: { 'Content-Type': 'application/json' },
        }
      );
    }

    // Upload file
    const fileId = await uploadFile(parseInt((session.user as any).id), file);

    return new Response(
      JSON.stringify({
        success: true,
        fileId,
        message: 'File uploaded successfully',
      }),
      {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  } catch (error: any) {
    console.error('Upload error:', error);
    return new Response(
      JSON.stringify({ error: error.message || 'Upload failed' }),
      {
        status: 500,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  }
}
"}

{"file_path": "src/app/api/files/download/[id]/route.ts", "initial_content": "import { auth } from '@/auth';
import { downloadFile, getFileMetadata } from '@/lib/uploads/storage';

export async function GET(
  request: Request,
  { params }: { params: { id: string } }
) {
  try {
    const session = await auth();

    if (!session?.user) {
      return new Response(JSON.stringify({ error: 'Unauthorized' }), {
        status: 401,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    const fileId = parseInt(params.id);

    if (isNaN(fileId)) {
      return new Response(JSON.stringify({ error: 'Invalid file ID' }), {
        status: 400,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    // Get file metadata and verify ownership
    const metadata = await getFileMetadata(fileId);

    // Download file
    const buffer = await downloadFile(fileId);

    return new Response(buffer, {
      status: 200,
      headers: {
        'Content-Type': metadata.mimeType || 'application/octet-stream',
        'Content-Disposition': `attachment; filename="${metadata.filename}"`,
        'Content-Length': metadata.size.toString(),
      },
    });
  } catch (error: any) {
    console.error('Download error:', error);

    if (error.message === 'File not found') {
      return new Response(JSON.stringify({ error: 'File not found' }), {
        status: 404,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    return new Response(
      JSON.stringify({ error: error.message || 'Download failed' }),
      {
        status: 500,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  }
}
"}

