{"file_path": "src/hooks/use-auth.ts", "initial_content": "'use client';

import { signIn, signOut, useSession } from 'next-auth/react';
import { useState } from 'react';

export interface AuthUser {
  id: string;
  email: string;
  name: string | null;
  image: string | null;
  role: string;
}

/**
 * Hook for accessing current user and auth functions
 * Replaces useFirebase() from Firebase
 */
export function useAuth() {
  const { data: session, status } = useSession();
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const user: AuthUser | null = session?.user
    ? {
        id: (session.user as any).id,
        email: session.user.email || '',
        name: session.user.name,
        image: session.user.image,
        role: (session.user as any).role || 'user',
      }
    : null;

  const handleSignIn = async (email: string, password: string) => {
    try {
      setIsLoading(true);
      setError(null);

      const result = await signIn('credentials', {
        email,
        password,
        redirect: false,
      });

      if (!result?.ok) {
        setError(result?.error || 'Sign in failed');
        return false;
      }

      return true;
    } catch (err) {
      const message = err instanceof Error ? err.message : 'An error occurred';
      setError(message);
      return false;
    } finally {
      setIsLoading(false);
    }
  };

  const handleSignUp = async (email: string, password: string, name: string) => {
    try {
      setIsLoading(true);
      setError(null);

      // Call signup API
      const response = await fetch('/api/users', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password, name }),
      });

      if (!response.ok) {
        const data = await response.json();
        setError(data.error || 'Sign up failed');
        return false;
      }

      // Sign in after successful signup
      return await handleSignIn(email, password);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'An error occurred';
      setError(message);
      return false;
    } finally {
      setIsLoading(false);
    }
  };

  const handleSignOut = async () => {
    try {
      setIsLoading(true);
      await signOut({ redirect: false });
      setError(null);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Sign out failed';
      setError(message);
    } finally {
      setIsLoading(false);
    }
  };

  return {
    user,
    isLoading: isLoading || status === 'loading',
    isAuthenticated: !!user,
    error,
    signIn: handleSignIn,
    signUp: handleSignUp,
    signOut: handleSignOut,
  };
}

/**
 * Hook to require authentication
 * Redirects to login if not authenticated
 */
export function useRequireAuth() {
  const { user, isLoading, isAuthenticated } = useAuth();

  if (!isLoading && !isAuthenticated) {
    // Will be handled by middleware
  }

  return { user, isLoading, isAuthenticated };
}

/**
 * Hook for accessing session directly
 * Lower-level than useAuth()
 */
export function useAuthSession() {
  const { data: session, status, update } = useSession();

  return {
    session,
    isLoading: status === 'loading',
    isAuthenticated: status === 'authenticated',
    update,
  };
}
"}

