{"file_path": "src/lib/error-handler.ts", "initial_content": "/**
 * Centralized error handling and logging
 */

export interface ApiError {
  code: string;
  message: string;
  status: number;
  details?: any;
}

export class AppError extends Error {
  constructor(
    public code: string,
    public status: number,
    message: string,
    public details?: any
  ) {
    super(message);
    this.name = 'AppError';
  }
}

// Common error codes
export const ErrorCodes = {
  // Auth errors
  UNAUTHORIZED: 'UNAUTHORIZED',
  FORBIDDEN: 'FORBIDDEN',
  INVALID_CREDENTIALS: 'INVALID_CREDENTIALS',
  USER_NOT_FOUND: 'USER_NOT_FOUND',
  EMAIL_ALREADY_EXISTS: 'EMAIL_ALREADY_EXISTS',
  SESSION_EXPIRED: 'SESSION_EXPIRED',

  // Database errors
  DATABASE_ERROR: 'DATABASE_ERROR',
  VALIDATION_ERROR: 'VALIDATION_ERROR',
  NOT_FOUND: 'NOT_FOUND',
  CONFLICT: 'CONFLICT',

  // File upload errors
  FILE_UPLOAD_FAILED: 'FILE_UPLOAD_FAILED',
  FILE_NOT_FOUND: 'FILE_NOT_FOUND',
  STORAGE_QUOTA_EXCEEDED: 'STORAGE_QUOTA_EXCEEDED',

  // Server errors
  INTERNAL_ERROR: 'INTERNAL_ERROR',
  SERVICE_UNAVAILABLE: 'SERVICE_UNAVAILABLE',
};

/**
 * Error logger
 */
export function logError(error: unknown, context?: string) {
  const timestamp = new Date().toISOString();

  if (error instanceof AppError) {
    console.error(`[${timestamp}] ${context || 'Error'}:`, {
      code: error.code,
      message: error.message,
      status: error.status,
      details: error.details,
    });
  } else if (error instanceof Error) {
    console.error(`[${timestamp}] ${context || 'Error'}:`, {
      message: error.message,
      stack: error.stack,
    });
  } else {
    console.error(`[${timestamp}] ${context || 'Error'}:`, error);
  }
}

/**
 * Convert error to API response
 */
export function errorToResponse(error: unknown) {
  if (error instanceof AppError) {
    return {
      success: false,
      error: {
        code: error.code,
        message: error.message,
      },
      status: error.status,
    };
  }

  if (error instanceof Error) {
    return {
      success: false,
      error: {
        code: ErrorCodes.INTERNAL_ERROR,
        message: error.message,
      },
      status: 500,
    };
  }

  return {
    success: false,
    error: {
      code: ErrorCodes.INTERNAL_ERROR,
      message: 'An unexpected error occurred',
    },
    status: 500,
  };
}

/**
 * Create error response
 */
export function createErrorResponse(
  error: unknown,
  context?: string
): Response {
  logError(error, context);
  const response = errorToResponse(error);

  return new Response(
    JSON.stringify({
      success: response.success,
      error: response.error,
    }),
    {
      status: response.status,
      headers: { 'Content-Type': 'application/json' },
    }
  );
}

/**
 * Create success response
 */
export function createSuccessResponse(data: any, status = 200): Response {
  return new Response(
    JSON.stringify({
      success: true,
      data,
    }),
    {
      status,
      headers: { 'Content-Type': 'application/json' },
    }
  );
}

/**
 * Handle API route errors with consistent format
 */
export async function handleApiRoute(
  handler: () => Promise<Response>,
  context?: string
): Promise<Response> {
  try {
    return await handler();
  } catch (error) {
    return createErrorResponse(error, context);
  }
}

/**
 * Validate required fields
 */
export function validateRequired(
  data: Record<string, any>,
  required: string[]
): string[] {
  return required.filter(field => !data[field]);
}

/**
 * Database error handler
 */
export function handleDatabaseError(error: unknown): AppError {
  logError(error, 'Database Error');

  if (error instanceof Error) {
    const message = error.message.toLowerCase();

    if (message.includes('unique')) {
      return new AppError(
        ErrorCodes.CONFLICT,
        409,
        'This record already exists',
        error.message
      );
    }

    if (message.includes('not found')) {
      return new AppError(
        ErrorCodes.NOT_FOUND,
        404,
        'Record not found',
        error.message
      );
    }

    if (message.includes('validation')) {
      return new AppError(
        ErrorCodes.VALIDATION_ERROR,
        400,
        'Validation failed',
        error.message
      );
    }
  }

  return new AppError(
    ErrorCodes.DATABASE_ERROR,
    500,
    'Database operation failed',
    error
  );
}
"}

{"file_path": "src/middleware.ts", "initial_content": "import { auth } from '@/auth';
import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';

// Routes that require authentication
const PROTECTED_ROUTES = [
  '/dashboard',
  '/builder',
  '/profile',
  '/projects',
  '/writing-tools',
  '/api/projects',
  '/api/users',
  '/api/files',
];

// Routes that should redirect to dashboard if authenticated
const AUTH_ROUTES = ['/login', '/signup', '/forgot-password'];

/**
 * Middleware for authentication and authorization
 */
export async function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;

  // Get session
  const session = await auth();
  const isAuthenticated = !!session?.user;

  // Check if route requires authentication
  const isProtected = PROTECTED_ROUTES.some(route => pathname.startsWith(route));

  // If route is protected and user is not authenticated, redirect to login
  if (isProtected && !isAuthenticated) {
    const loginUrl = new URL('/login', request.url);
    loginUrl.searchParams.set('redirect', pathname);
    return NextResponse.redirect(loginUrl);
  }

  // If user is authenticated and tries to access auth routes, redirect to dashboard
  if (isAuthenticated && AUTH_ROUTES.includes(pathname)) {
    return NextResponse.redirect(new URL('/dashboard', request.url));
  }

  // Continue to next middleware/handler
  return NextResponse.next();
}

export const config = {
  matcher: [
    // Match all routes except static files and api auth
    '/((?!_next/static|_next/image|favicon.ico|api/auth).*)',
  ],
};
"}

{"file_path": "src/app/api/sections/route.ts", "initial_content": "import { auth } from '@/auth';
import { db } from '@/db';
import { sections, projects } from '@/db/schema';
import { eq, and } from 'drizzle-orm';
import { z } from 'zod';
import { createErrorResponse, createSuccessResponse, handleDatabaseError } from '@/lib/error-handler';

const createSectionSchema = z.object({
  projectId: z.number('Project ID must be a number'),
  title: z.string().min(1, 'Title is required'),
  content: z.string().optional(),
  order: z.number().optional(),
});

/**
 * Get sections for a project
 */
export async function GET(request: Request) {
  try {
    const session = await auth();
    if (!session?.user) {
      return createErrorResponse('Unauthorized', 'GET sections');
    }

    const { searchParams } = new URL(request.url);
    const projectId = searchParams.get('projectId');

    if (!projectId) {
      return createErrorResponse('Project ID is required', 'GET sections');
    }

    const userId = parseInt((session.user as any).id);
    const projectIdNum = parseInt(projectId);

    // Verify user owns the project
    const project = await db.query.projects.findFirst({
      where: and(eq(projects.id, projectIdNum), eq(projects.userId, userId)),
    });

    if (!project) {
      return createErrorResponse('Project not found or unauthorized', 'GET sections');
    }

    const projectSections = await db.query.sections.findMany({
      where: eq(sections.projectId, projectIdNum),
    });

    return createSuccessResponse(projectSections);
  } catch (error) {
    return createErrorResponse(error, 'GET sections');
  }
}

/**
 * Create a new section
 */
export async function POST(request: Request) {
  try {
    const session = await auth();
    if (!session?.user) {
      return createErrorResponse('Unauthorized', 'POST section');
    }

    const body = await request.json();
    const validation = createSectionSchema.safeParse(body);

    if (!validation.success) {
      return createErrorResponse(validation.error.errors, 'POST section');
    }

    const { projectId, title, content, order } = validation.data;
    const userId = parseInt((session.user as any).id);

    // Verify user owns the project
    const project = await db.query.projects.findFirst({
      where: and(eq(projects.id, projectId), eq(projects.userId, userId)),
    });

    if (!project) {
      return createErrorResponse('Project not found or unauthorized', 'POST section');
    }

    // Get the next order if not provided
    const nextOrder = order ?? await getNextSectionOrder(projectId);

    const [newSection] = await db.insert(sections).values({
      projectId,
      title,
      content: content || '',
      order: nextOrder,
      status: 'draft',
    }).returning();

    return createSuccessResponse(newSection, 201);
  } catch (error) {
    const dbError = handleDatabaseError(error);
    return createErrorResponse(dbError, 'POST section');
  }
}

/**
 * Get next section order number
 */
async function getNextSectionOrder(projectId: number): Promise<number> {
  const lastSection = await db.query.sections.findFirst({
    where: eq(sections.projectId, projectId),
  });

  return lastSection ? (lastSection.order || 0) + 1 : 0;
}
"}

{"file_path": "src/app/api/sections/[id]/route.ts", "initial_content": "import { auth } from '@/auth';
import { db } from '@/db';
import { sections, projects } from '@/db/schema';
import { eq, and } from 'drizzle-orm';
import { z } from 'zod';
import { createErrorResponse, createSuccessResponse, handleDatabaseError } from '@/lib/error-handler';

const updateSectionSchema = z.object({
  title: z.string().min(1).optional(),
  content: z.string().optional(),
  order: z.number().optional(),
  status: z.string().optional(),
});

/**
 * Get a specific section
 */
export async function GET(
  request: Request,
  { params }: { params: { id: string } }
) {
  try {
    const session = await auth();
    if (!session?.user) {
      return createErrorResponse('Unauthorized', 'GET section');
    }

    const sectionId = parseInt(params.id);
    const userId = parseInt((session.user as any).id);

    // Get section and verify user owns the project
    const section = await db.query.sections.findFirst({
      where: eq(sections.id, sectionId),
      with: {
        project: true,
      },
    });

    if (!section) {
      return createErrorResponse('Section not found', 'GET section');
    }

    if (section.project?.userId !== userId) {
      return createErrorResponse('Unauthorized', 'GET section');
    }

    return createSuccessResponse(section);
  } catch (error) {
    return createErrorResponse(error, 'GET section');
  }
}

/**
 * Update a section
 */
export async function PATCH(
  request: Request,
  { params }: { params: { id: string } }
) {
  try {
    const session = await auth();
    if (!session?.user) {
      return createErrorResponse('Unauthorized', 'PATCH section');
    }

    const sectionId = parseInt(params.id);
    const userId = parseInt((session.user as any).id);

    const body = await request.json();
    const validation = updateSectionSchema.safeParse(body);

    if (!validation.success) {
      return createErrorResponse(validation.error.errors, 'PATCH section');
    }

    // Verify user owns the project
    const section = await db.query.sections.findFirst({
      where: eq(sections.id, sectionId),
      with: {
        project: true,
      },
    });

    if (!section) {
      return createErrorResponse('Section not found', 'PATCH section');
    }

    if (section.project?.userId !== userId) {
      return createErrorResponse('Unauthorized', 'PATCH section');
    }

    const [updatedSection] = await db.update(sections)
      .set({
        ...validation.data,
        updatedAt: new Date(),
      })
      .where(eq(sections.id, sectionId))
      .returning();

    return createSuccessResponse(updatedSection);
  } catch (error) {
    const dbError = handleDatabaseError(error);
    return createErrorResponse(dbError, 'PATCH section');
  }
}

/**
 * Delete a section
 */
export async function DELETE(
  request: Request,
  { params }: { params: { id: string } }
) {
  try {
    const session = await auth();
    if (!session?.user) {
      return createErrorResponse('Unauthorized', 'DELETE section');
    }

    const sectionId = parseInt(params.id);
    const userId = parseInt((session.user as any).id);

    // Verify user owns the project
    const section = await db.query.sections.findFirst({
      where: eq(sections.id, sectionId),
      with: {
        project: true,
      },
    });

    if (!section) {
      return createErrorResponse('Section not found', 'DELETE section');
    }

    if (section.project?.userId !== userId) {
      return createErrorResponse('Unauthorized', 'DELETE section');
    }

    await db.delete(sections).where(eq(sections.id, sectionId));

    return createSuccessResponse({ id: sectionId, deleted: true });
  } catch (error) {
    const dbError = handleDatabaseError(error);
    return createErrorResponse(dbError, 'DELETE section');
  }
}
"}

