{"file_path": "src/app/api/health/route.ts", "initial_content": "import { db, checkDatabaseConnection } from '@/db';
import { createSuccessResponse, createErrorResponse } from '@/lib/error-handler';

/**
 * Health check endpoint
 * Returns system status and database connection info
 */
export async function GET(request: Request) {
  try {
    const startTime = Date.now();

    // Check database connection
    const dbCheck = await checkDatabaseConnection();
    const dbLatency = Date.now() - startTime;

    const health = {
      status: dbCheck.connected ? 'healthy' : 'degraded',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      database: {
        connected: dbCheck.connected,
        latency: `${dbLatency}ms`,
        error: dbCheck.error ? String(dbCheck.error) : null,
      },
      environment: process.env.NODE_ENV,
      version: '1.0.0',
    };

    return createSuccessResponse(health, dbCheck.connected ? 200 : 503);
  } catch (error) {
    console.error('Health check failed:', error);
    return createErrorResponse(error, 'GET health');
  }
}
"}

