{"file_path": "src/db/firebase-to-postgres-migration.ts", "initial_content": "/**
 * Firebase to PostgreSQL Migration Script
 * Extracts all data from Firebase and migrates to PostgreSQL
 */

import { db as pgDb } from './index';
import {
  collection,
  getDocs,
  query,
  orderBy,
  limit,
  Query,
  QueryConstraint,
} from 'firebase/firestore';
import { initializeApp } from 'firebase/app';
import { getFirestore } from 'firebase/firestore';
import { getAuth, listUsers } from 'firebase/auth';
import bcrypt from 'bcryptjs';
import { v4 as uuidv4 } from 'uuid';

// Initialize Firebase Admin SDK for user extraction
const firebaseConfig = {
  apiKey: process.env.NEXT_PUBLIC_FIREBASE_API_KEY,
  authDomain: process.env.NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN,
  projectId: process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID,
  storageBucket: process.env.NEXT_PUBLIC_FIREBASE_STORAGE_BUCKET,
  messagingSenderId: process.env.NEXT_PUBLIC_FIREBASE_MESSAGING_SENDER_ID,
  appId: process.env.NEXT_PUBLIC_FIREBASE_APP_ID,
};

const firebaseApp = initializeApp(firebaseConfig);
const firestore = getFirestore(firebaseApp);

interface FirebaseUser {
  id: string;
  email: string;
  displayName?: string;
  photoURL?: string;
  credits?: number;
  role?: string;
  language?: string;
  createdAt?: any;
  updatedAt?: any;
}

interface FirebaseProject {
  id: string;
  userId: string;
  title: string;
  description?: string;
  content?: string;
  status?: string;
  language?: string;
  metadata?: any;
  createdAt?: any;
  updatedAt?: any;
}

interface FirebaseSection {
  id: string;
  projectId: string;
  title: string;
  content?: string;
  order?: number;
  status?: string;
  metadata?: any;
  wordCount?: number;
  createdAt?: any;
  updatedAt?: any;
}

/**
 * Fetch all users from Firestore
 */
async function fetchFirebaseUsers(): Promise<FirebaseUser[]> {
  console.log('📥 Fetching users from Firebase...');
  try {
    const usersRef = collection(firestore, 'users');
    const snapshot = await getDocs(usersRef);
    const users = snapshot.docs.map((doc) => ({
      id: doc.id,
      ...doc.data(),
    })) as FirebaseUser[];
    console.log(`✅ Fetched ${users.length} users`);
    return users;
  } catch (error) {
    console.error('❌ Error fetching users:', error);
    return [];
  }
}

/**
 * Fetch all projects from Firestore
 */
async function fetchFirebaseProjects(): Promise<FirebaseProject[]> {
  console.log('📥 Fetching projects from Firebase...');
  try {
    const projectsRef = collection(firestore, 'projects');
    const snapshot = await getDocs(projectsRef);
    const projects = snapshot.docs.map((doc) => ({
      id: doc.id,
      ...doc.data(),
    })) as FirebaseProject[];
    console.log(`✅ Fetched ${projects.length} projects`);
    return projects;
  } catch (error) {
    console.error('❌ Error fetching projects:', error);
    return [];
  }
}

/**
 * Fetch all sections from Firestore
 */
async function fetchFirebaseSections(): Promise<FirebaseSection[]> {
  console.log('📥 Fetching sections from Firebase...');
  try {
    const sectionsRef = collection(firestore, 'sections');
    const snapshot = await getDocs(sectionsRef);
    const sections = snapshot.docs.map((doc) => ({
      id: doc.id,
      ...doc.data(),
    })) as FirebaseSection[];
    console.log(`✅ Fetched ${sections.length} sections`);
    return sections;
  } catch (error) {
    console.error('❌ Error fetching sections:', error);
    return [];
  }
}

/**
 * Fetch all templates from Firestore
 */
async function fetchFirebaseTemplates(): Promise<any[]> {
