{"file_path": "src/context/AuthContext.tsx", "initial_content": "'use client';

import { useSession } from 'next-auth/react';
import { useBuilderStore } from '@/hooks';
import { User } from '@/lib/models';
import { userKeys } from '@/lib/query-keys';
import { fetchUserProfileApi } from '@/services';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { createContext, ReactNode, useCallback, useContext, useEffect, useState } from 'react';

interface AuthContextType {
  user: any | null;
  userProfile: User | null;
  isLoading: boolean;
  isGuest: boolean;
  refetchUser: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider = ({ children }: { children: ReactNode }) => {
  const { data: session, status } = useSession();
  const [isGuest, setIsGuest] = useState(false);
  const queryClient = useQueryClient();
  const { setUserProfile } = useBuilderStore();

  // Get user profile from API
  const { data: userProfile, isLoading: isProfileLoading } = useQuery<User | null>({
    queryKey: userKeys.profile(session?.user?.id ?? ''),
    queryFn: async () => {
      if (!session?.user?.id) return null;
      const userProfileData = await fetchUserProfileApi(session.user.id);
      const userInstance = userProfileData ? new User(userProfileData) : null;
      setUserProfile(userInstance);
      return userInstance;
    },
    enabled: !!session?.user?.id,
    staleTime: Infinity,
  });

  const refetchUser = useCallback(() => {
    if (session?.user?.id) {
      queryClient.invalidateQueries({ queryKey: userKeys.profile(session.user.id) });
    }
  }, [session?.user?.id, queryClient]);

  useEffect(() => {
    const guestCookieExists = typeof window !== 'undefined' && document.cookie.includes('__guest=true');

    if (session?.user) {
      setIsGuest(false);
      if (guestCookieExists) {
        document.cookie = '__guest=; Max-Age=-99999999; path=/;';
      }
    } else {
      setIsGuest(guestCookieExists);
      if (!guestCookieExists) {
        queryClient.clear();
        setUserProfile(null);
      }
    }
  }, [session, queryClient, setUserProfile]);

  const value = {
    user: session?.user || null,
    userProfile: userProfile ?? null,
    isLoading: status === 'loading' || (!!session?.user && isProfileLoading),
    isGuest,
    refetchUser,
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = (): AuthContextType => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};
