import { db } from '@/db';
import { users, projects, transactions, generation_history } from '@/db/schema';
import { count, eq, gte } from 'drizzle-orm';
import { NextResponse } from 'next/server';

async function getSummaryCounts() {
  const totalUsers = await db.select({ count: count() }).from(users);
  const totalGenerations = await db.select({ count: count() }).from(generation_history);
  const pendingTransactions = await db.select({ count: count() }).from(transactions).where(eq(transactions.status, 'pending'));

  return {
    totalUsers: totalUsers[0]?.count || 0,
    totalGenerations: totalGenerations[0]?.count || 0,
    pendingPayments: pendingTransactions[0]?.count || 0,
  };
}

async function getAgentUsage() {
  const thirtyDaysAgo = new Date();
  thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

  const agentGenerations = await db.select().from(generation_history)
    .where(gte(generation_history.createdAt, thirtyDaysAgo));

  const agentUsage: Record<string, number> = {};
  agentGenerations.forEach(doc => {
    const agentId = doc.agentId;
    if (agentId) {
      agentUsage[agentId] = (agentUsage[agentId] || 0) + 1;
    }
  });

  return Object.entries(agentUsage)
    .map(([agentId, count]) => ({
      agentId,
      count,
    }))
    .sort((a, b) => b.count - a.count)
    .slice(0, 10);
}

async function getRecentActivity() {
  const recentGenerations = await db.select().from(generation_history)
    .orderBy(generation_history.createdAt)
    .limit(5);

  return recentGenerations.map(doc => ({
    id: doc.id,
    userId: doc.userId,
    action: 'generation',
    ...doc
  }));
}

export async function GET(request: Request) {
  try {
    const session = await auth();

    if (!session?.user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const [summaryCounts, agentUsageChartData, recentActivity] = await Promise.all([
      getSummaryCounts(),
      getAgentUsage(),
      getRecentActivity(),
    ]);

    const stats = {
      ...summaryCounts,
      agentUsageChartData,
      recentActivity
    };

    return NextResponse.json(stats, { status: 200 });

  } catch (error) {
    console.error('Dashboard stats error:', error);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}
